/// Regression test: a sibling package sharing a name prefix
/// ("foo-bar" installed) must not be misread as an installed version
/// of "foo" when scanning the vdb category directory. Without the
/// digit-start guard in strip_version_prefix, this would wrongly
/// report an Upgrade from a bogus "bar-2.0" pseudo-version instead of
/// a clean New.
#[test]
fn sibling_package_prefix_does_not_contaminate_vdb_scan() {
    assert_eq!(
        resolve("dev-libs", "foo"),
        PretendOutcome::New {
            version: "1.0".to_string()
        }
    );
    assert_eq!(
        resolve("dev-libs", "foo-bar"),
        PretendOutcome::AlreadyInstalled {
            version: "2.0".to_string()
        }
    );
}

fn graph_with(
    atom_str: &str,
    tweak: impl FnOnce(&mut ResolveRequest),
) -> Vec<(String, PretendOutcome)> {
    let root = fixtures_root();
    let mut request = ResolveRequest::new(
        &root,
        &root,
        &[atom_str.to_string()],
        &test_config(),
        &fixtures_root().join("distfiles"),
    );
    tweak(&mut request);
    request
        .resolve()
        .unwrap_or_else(|e| panic!("resolving {atom_str} failed: {e}"))
        .entries
        .into_iter()
        .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
        .collect()
}

fn graph(atom_str: &str) -> Vec<(String, PretendOutcome)> {
    graph_with(atom_str, |_| {})
}

/// Backlog #194: resolve one atom as an `--onlydeps` root with the
/// given `--onlydeps-with-*` values, over the shared fixture tree --
/// the unit-level counterpart of the `odw0*` contract cells. A full
/// `ResolveRequest` (like production's own `run_resolve` builds it),
/// since the legacy marshaller answers with onlydeps off.
fn graph_onlydeps(
    atom_str: &str,
    with_rdeps: bool,
    with_ideps: bool,
) -> Vec<(String, PretendOutcome)> {
    let root = fixtures_root();
    let req = ResolveRequest {
        config_root: root.clone(),
        root: root.clone(),
        atoms: vec![atom_str.to_string()],
        config: test_config(),
        newuse: false,
        changed_use: false,
        nodeps: false,
        onlydeps: true,
        onlydeps_with_rdeps: with_rdeps,
        onlydeps_with_ideps: with_ideps,
        update: false,
        deep: Deep::NotRequested,
        excluded: Vec::new(),
        with_bdeps: true,
        changed_deps: false,
        changed_slot: false,
        with_test_deps: false,
        changed_deps_report: false,
        selective: false,
        autounmask_suggest_keywords: false,
        autounmask_suggest_use: false,
        autounmask_suggest_license: false,
        autounmask_suggest_masks: false,
        usepkg: false,
        usepkgonly: false,
        binpkg_respect_use: false,
        usepkg_exclude: Vec::new(),
        usepkg_include: Vec::new(),
        rebuilt_binaries: false,
        rebuilt_binaries_timestamp: None,
        newrepo: false,
        buildpkgonly: false,
        root_deps_running_root: None,
        distdir: root.join("distfiles"),
        empty: false,
        getbinpkg: false,
        ignore_built_slot_operator_deps: false,
        backtrack_max: 10,
        reinstall_atoms: Vec::new(),
        rebuild_if_new_slot: true,
        rebuild_if_unbuilt: false,
        rebuild_if_new_rev: false,
        rebuild_if_new_ver: false,
        rebuild_exclude: Vec::new(),
        rebuild_ignore: Vec::new(),
        dynamic_deps: true,
        implicit_system_deps: true,
        complete: false,
        set_args: std::collections::HashSet::new(),
        solver: SolverKind::Portage,
    };
    active_resolver()
        .resolve(&req)
        .unwrap_or_else(|e| panic!("resolve({atom_str}) failed: {e}"))
        .entries
        .into_iter()
        .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
        .collect()
}

/// Backlog #194: `--onlydeps-with-rdeps` / `--onlydeps-with-ideps`
/// blank an onlydeps root's dep classes exactly like real
/// `depgraph.py:4186-4193` (sets asserted against the
/// `/tmp/opencode/n194/oracle_odw.log` playground oracle; the root
/// itself is always resolved -- only the display layer suppresses
/// it -- so it stays in the entries here).
#[test]
fn onlydeps_with_rdeps_and_ideps_blank_the_root_dep_classes() {
    let names = |entries: Vec<(String, PretendOutcome)>| {
        let mut names: Vec<String> = entries.into_iter().map(|(n, _)| n).collect();
        names.sort();
        names
    };
    // Default (rdeps on): every class walked.
    assert_eq!(
        names(graph_onlydeps("dev-libs/odw0a", true, false)),
        vec![
            "dev-libs/odw0a",
            "dev-libs/odw0b",
            "dev-libs/odw0c",
            "dev-libs/odw0d",
            "dev-libs/odw0e",
            "dev-libs/odw0f",
        ],
        "default"
    );
    // with-rdeps=n: build-time keys (DEPEND B, BDEPEND F) only.
    assert_eq!(
        names(graph_onlydeps("dev-libs/odw0a", false, false)),
        vec!["dev-libs/odw0a", "dev-libs/odw0b", "dev-libs/odw0f"],
        "with-rdeps=n"
    );
    // with-rdeps=n + with-ideps=y: IDEPEND E restored.
    assert_eq!(
        names(graph_onlydeps("dev-libs/odw0a", false, true)),
        vec![
            "dev-libs/odw0a",
            "dev-libs/odw0b",
            "dev-libs/odw0e",
            "dev-libs/odw0f",
        ],
        "with-rdeps=n with-ideps=y"
    );
}

/// Backlog #194: an EAPI-7 root's `IDEPEND` never reaches the walk
/// (real `bin/ebuild.sh` unsets it in the depend phase), so even the
/// default rdeps-on shape merges no `E`.
#[test]
fn onlydeps_eapi7_root_ignores_idepend() {
    let mut names: Vec<String> = graph_onlydeps("dev-libs/odw0g", true, false)
        .into_iter()
        .map(|(n, _)| n)
        .collect();
    names.sort();
    assert_eq!(
        names,
        vec![
            "dev-libs/odw0b",
            "dev-libs/odw0c",
            "dev-libs/odw0d",
            "dev-libs/odw0g",
        ]
    );
}
/// Backlog #194 (review round 1): under `--onlydeps
/// --onlydeps-with-rdeps=n --onlydeps-with-ideps=y` on an EAPI-8
/// root, real keeps walking `IDEPEND` (`depgraph.py:4186-4193`;
/// oracle cell `[B, E, F]`), so an atom present in both a
/// build-time key and `IDEPEND` is a runtime edge -- not
/// `buildtime_hard` (real `DepPriority`: an unbreakable
/// merge-order edge). Pinned at the classification level: the key
/// selection still carries `IDEPEND`, and one shared atom enqueued
/// with those sets lands soft.
#[test]
fn onlydeps_ideps_atom_shared_with_buildtime_key_is_not_buildtime_hard() {
    // rdeps blanked, ideps kept, EAPI 8: IDEPEND still classifies;
    // with ideps blanked (or below EAPI 8) nothing does.
    assert_eq!(onlydeps_runtime_keys(true, false, true), &["IDEPEND"][..]);
    assert!(onlydeps_runtime_keys(true, true, true).is_empty());
    assert!(onlydeps_runtime_keys(true, false, false).is_empty());
    let flatten = |text: &str| -> HashSet<String> {
        let toks: Vec<String> = text.split_whitespace().map(String::from).collect();
        let use_flags: HashSet<String> = HashSet::new();
        portage_use_reduce::use_reduce_flat(
            &toks,
            &use_flags,
            portage_use_reduce::MatchMode::Normal,
        )
        .map(|v| v.into_iter().filter(|t| t != "||").collect())
        .unwrap_or_default()
    };
    // One atom in both a build-time key and the walked IDEPEND.
    let buildtime_atoms = flatten("dev-libs/odw0e");
    let runtime_atoms = flatten("dev-libs/odw0e");
    assert!(buildtime_atoms.contains("dev-libs/odw0e"));
    assert!(runtime_atoms.contains("dev-libs/odw0e"));
    let mut queue = VecDeque::new();
    let mut blockers = Vec::new();
    enqueue_flat_deps(
        vec!["dev-libs/odw0e".to_string()],
        &("dev-libs".to_string(), "odw0a".to_string()),
        "1",
        1,
        &HashSet::new(),
        &mut queue,
        &mut blockers,
        &buildtime_atoms,
        &runtime_atoms,
        &HashSet::new(),
        &HashSet::new(),
        &HashSet::new(),
        false,
    );
    assert_eq!(queue.len(), 1);
    assert!(
        !queue[0].buildtime_hard,
        "an IDEPEND-walked atom is a runtime edge even when rdeps are blanked"
    );
}

/// Backlog #194 (review round 1): the read-time EAPI gate drops
/// `IDEPEND` from an EAPI-7 cache entry that still carries it.
/// Real `egencache` could never emit such an entry (real
/// `bin/ebuild.sh`'s `depend` phase unsets `IDEPEND` below EAPI 8),
/// so no fixture pins this path -- the adversarial entry is fed to
/// the gate directly.
#[test]
fn eapi7_cache_entry_carrying_idepend_is_gated_at_read_time() {
    // EAPI 7 + IDEPEND present: dropped even with no onlydeps
    // blanking.
    assert!(!onlydeps_walk_dep_key("IDEPEND", false, false, false));
    // EAPI 8 keeps it under the default flags ...
    assert!(onlydeps_walk_dep_key("IDEPEND", true, false, false));
    // ... but rdeps=n + ideps=n drops it there too.
    assert!(!onlydeps_walk_dep_key("IDEPEND", true, true, true));
    // Build-time keys are never gated; RDEPEND/PDEPEND fall to the
    // rdeps blank only.
    assert!(onlydeps_walk_dep_key("DEPEND", false, true, true));
    assert!(onlydeps_walk_dep_key("BDEPEND", false, true, true));
    assert!(!onlydeps_walk_dep_key("RDEPEND", false, true, true));
    assert!(onlydeps_walk_dep_key("RDEPEND", true, false, false));
}
/// instance's own slot (real's `pkg.slot_atom` node identity), not
/// the cp. `fixtures/var/db/pkg` has `dev-libs/slotdedup-1.0` (slot
/// 1, no deps) and `slotdedup-2.0` (slot 2, RDEPEND
/// `dev-libs/slotdedupmarker`) installed;
/// `fixtures/repo/dev-libs/slotdedupconsumer-1.0` RDEPENDs
/// `dev-libs/slotdedup:1 dev-libs/slotdedup:2` (slot 1 first). With
/// the old cp-keyed dedup the slot-2 visit was dropped, so its deps
/// were never walked and `slotdedupmarker` never entered the graph --
/// the #74 class B1 shape (`llvm-core/clang:22` shadowing `:23`,
/// losing myst-parser).
#[test]
fn other_outcomes_dedups_installed_instances_by_slot_not_cp() {
    let entries = graph_deep("dev-libs/slotdedupconsumer", Deep::Unlimited);
    let names: Vec<&str> = entries.iter().map(|(n, _)| n.as_str()).collect();
    assert!(names.contains(&"dev-libs/slotdedupconsumer"), "{names:?}");
    assert!(
        names.contains(&"dev-libs/slotdedupmarker"),
        "slot 2's own deps must be walked: {names:?}"
    );
}

/// #74 S1: an installed `||` alternative's `[use]` deps are matched
/// against its recorded vdb USE, not the tree candidate's
/// profile-derived USE (real `dep_check.dep_zapdeps`'s
/// `_dep_check_composite_db` covers the vardb, and `dbapi._match_use`
/// has a separate built-package branch that reads `metadata["USE"]`).
/// `fixtures/repo/dev-libs/altconsumer-1.0` BDEPENDs
/// `|| ( dev-libs/altprov:1.1[flip] dev-libs/altprov:1.0 )`;
/// `fixtures/var/db/pkg/dev-libs/altprov-1.1` is installed with
/// `USE=flip` while the fixture profile/environment never enables
/// `flip`. Before the fix the installed alternative ranked
/// `UnsatUseInstalled` and the uninstalled slot's cp-level
/// `Installed` won, so portuale merged `dev-libs/altprov-1.0`; real's
/// own container capture (findings "#74 S0") keeps the installed
/// `:1.1` (bin 0 plus the `all_installed_slots` promotion).
#[test]
fn disjunction_preference_matches_an_installed_alternatives_vdb_use() {
    let entries = graph("dev-libs/altconsumer");
    assert!(
        entries
            .iter()
            .any(|(name, _)| name == "dev-libs/altconsumer"),
        "{entries:?}"
    );
    let altprov_merges: Vec<&(String, PretendOutcome)> = entries
        .iter()
        .filter(|(name, outcome)| {
            name == "dev-libs/altprov"
                && matches!(
                    outcome,
                    PretendOutcome::New { .. }
                        | PretendOutcome::Upgrade { .. }
                        | PretendOutcome::Downgrade { .. }
                        | PretendOutcome::Reinstall { .. }
                )
        })
        .collect();
    assert!(
        altprov_merges.is_empty(),
        "the installed altprov:1.1[flip] must win the || group: {entries:?}"
    );
}

/// #148: a *surviving* slot conflict keeps both same-slot
/// instances as merge rows (real's `l0-fx-20260922T192350Z` cell
/// `-D dev-libs/slotusegroup`: `[ebuild N] slotusetarget-1.0`
/// *and* `-2.0`, rc 1). `dev-libs/slotusegroup` RDEPENDs
/// `slotuseplain slotusex slotusey`; slotusey/slotusex pull
/// `>=slotusetarget-1.0[y]` / `[x]` (2.0 lacks `y` in IUSE and
/// has `x` default-off) while slotuseplain pulls
/// `>=slotusetarget-2.0`. Before the fix the walk's
/// `resolved_slots` conflict arm recorded the `SlotConflict`
/// and continued past `GraphEntry` creation, so the graph held
/// one `slotusetarget` entry (1.0) and the merge list one row.
#[test]
fn surviving_slot_conflict_graphs_both_same_slot_instances() {
    let entries = graph_deep("dev-libs/slotusegroup", Deep::Unlimited);
    let mut versions: Vec<&str> = entries
        .iter()
        .filter(|(name, _)| name == "dev-libs/slotusetarget")
        .map(|(_, outcome)| match outcome {
            PretendOutcome::New { version } => version.as_str(),
            PretendOutcome::Upgrade { to, .. } | PretendOutcome::Downgrade { to, .. } => {
                to.as_str()
            }
            PretendOutcome::Reinstall { version, .. } => version.as_str(),
            _ => panic!("slotusetarget entry is not merge-bound: {entries:?}"),
        })
        .collect();
    versions.sort_unstable();
    assert_eq!(
        versions,
        vec!["1.0", "2.0"],
        "both conflicting instances must be graphed: {entries:?}"
    );
}

/// #131 S1: resolve a multi-atom fixture graph with `--update`,
/// returning full entries (the `graph*` helpers above map to
/// name/outcome pairs only, which cannot drive a display order).
/// Argument list mirrors `graph()` with the `update` slot on.
fn graph_update_entries(atoms: &[&str], config: &portage_profile::Config) -> Vec<GraphEntry> {
    let root = fixtures_root();
    let owned: Vec<String> = atoms.iter().map(|a| a.to_string()).collect();
    ResolveRequest {
        update: true,
        ..ResolveRequest::new(
            &root,
            &root,
            &owned,
            config,
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolving {owned:?} failed: {e}"))
    .entries
}

/// #131 S1: `tree_display_order` sequences the p2b tree like real's
/// tree-mode retlist (bed `l0-fx-20260924T090502Z`: real's display
/// walks `[p2bowner, newpkg, (nomerge p2bowner,) blocks b,
/// p2btarget]`, i.e. merge direction `[p2btarget, newpkg,
/// p2bowner]`). The entries are first put in the display-time
/// (flat merge) order `[newpkg, p2btarget, p2bowner]` -- pinned
/// independently by the flat pin -- because the scheduler's
/// discovery seed follows the input Vec order, and `run()` hands
/// `print_tree` the merge-ordered slice, not resolver order
/// (everything `tree_display_order` reads -- deps, blockers,
/// `required_by` -- is value-addressed, so the reorder is safe).
#[test]
fn tree_display_order_sequences_the_p2b_tree_like_portage() {
    let atoms = vec![
        "dev-libs/p2btarget".to_string(),
        "dev-libs/p2bowner".to_string(),
        "dev-libs/newpkg".to_string(),
    ];
    // The `@system` seed matters: the fixture profile lists
    // `*dev-libs/newpkg` in `repo/profiles/base/packages`, and the
    // display-time run resolves with that profile config -- so the
    // bias pulls `newpkg` first exactly like real's own bias does.
    // Plain `test_config()` has an empty system set and would seed
    // nothing (its batch comes out `[owner, newpkg]`).
    let mut order_config = test_config();
    order_config.system_packages = vec!["dev-libs/newpkg".to_string()];
    let mut entries = graph_update_entries(
        &["dev-libs/p2btarget", "dev-libs/p2bowner", "dev-libs/newpkg"],
        &order_config,
    );
    // The resolve must still graph exactly the three merge-bound
    // entries -- the system seed reorders, never re-members.
    let mut names: Vec<String> = entries
        .iter()
        .map(|e| format!("{}/{}", e.category, e.package))
        .collect();
    names.sort_unstable();
    assert_eq!(
        names,
        vec!["dev-libs/newpkg", "dev-libs/p2bowner", "dev-libs/p2btarget"],
        "system seed must not change p2b membership: {names:?}"
    );
    let root = fixtures_root();
    let repos = find_repos(&root).expect("repos");
    // Display-time (merge) order, as `run()` passes it: the
    // scheduler's discovery seed follows the input Vec order.
    let rank = |e: &GraphEntry| match (e.category.as_str(), e.package.as_str()) {
        ("dev-libs", "newpkg") => 0,
        ("dev-libs", "p2btarget") => 1,
        ("dev-libs", "p2bowner") => 2,
        (c, p) => panic!("unexpected entry in p2b graph: {c}/{p}"),
    };
    entries.sort_by_key(rank);
    let order = merge_order::tree_display_order(
        &entries,
        &atoms,
        &order_config,
        &root,
        true,
        &repos,
        true,
        &HashMap::new(),
    );
    let names: Vec<String> = order
        .iter()
        .map(|&i| format!("{}/{}", entries[i].category, entries[i].package))
        .collect();
    assert_eq!(
        names,
        vec!["dev-libs/p2btarget", "dev-libs/newpkg", "dev-libs/p2bowner"],
        "tree-mode retlist order, merge direction: {names:?}"
    );
}

/// #131 S1: an admitted removal waits on its owner in tree mode
/// (real reverses the validation edge on admission,
/// `depgraph.py:9998-10020`). u1's tree retlist is `[blockerpkg,
/// samepkg-uninstall, (Blocker appended at selection)]` — the owner
/// first. Without the wait the one-at-a-time pick takes the removal
/// (it has parents, the owner does not) and the display opens on the
/// merge row, losing real's leading `[nomerge]` ancestor.
#[test]
fn tree_display_order_schedules_an_admitted_removal_after_its_owner() {
    let atoms = vec!["dev-libs/blockerpkg".to_string()];
    let entries = graph_update_entries(&["dev-libs/blockerpkg"], &test_config());
    let root = fixtures_root();
    let repos = find_repos(&root).expect("repos");
    let order = merge_order::tree_display_order(
        &entries,
        &atoms,
        &test_config(),
        &root,
        true,
        &repos,
        true,
        &HashMap::new(),
    );
    let names: Vec<String> = order
        .iter()
        .map(|&i| format!("{}/{}", entries[i].category, entries[i].package))
        .collect();
    assert_eq!(
        names,
        vec!["dev-libs/blockerpkg", "dev-libs/samepkg"],
        "owner before its admitted removal: {names:?}"
    );
    assert!(
        matches!(entries[order[1]].outcome, PretendOutcome::Uninstall { .. }),
        "second node is the uninstall: {:?}",
        entries[order[1]].outcome
    );
}

/// Like `graph`, but with `--nodeps` enabled.
fn graph_nodeps(atom_str: &str) -> Vec<(String, PretendOutcome)> {
    graph_with(atom_str, |r| r.nodeps = true)
}

/// Like `graph`, but with `--update` enabled -- proves `update` threads
/// through the whole BFS, not just a top-level atom (see
/// `resolve_pretend_graph`'s own doc comment).
fn graph_update(atom_str: &str) -> Vec<(String, PretendOutcome)> {
    graph_with(atom_str, |r| r.update = true)
}

#[test]
fn exclude_threads_through_dependency_recursion_not_just_top_level() {
    // dev-libs/upgradepkg is reached only as a dependency of
    // dev-libs/withdeps here, never a top-level atom -- --exclude
    // must still leave it alone despite --update, proving the flag
    // threads uniformly through the whole BFS (see
    // resolve_pretend_graph's own doc comment), not just a
    // top-level atom.
    let root = fixtures_root();
    let entries: Vec<(String, PretendOutcome)> = ResolveRequest {
        update: true,
        excluded: vec!["dev-libs/upgradepkg".to_string()],
        ..ResolveRequest::new(
            &root,
            &root,
            &["dev-libs/withdeps".to_string()],
            &test_config(),
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolve_pretend_graph failed: {e}"))
    .entries
    .into_iter()
    .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
    .collect();
    assert_eq!(
        entries,
        vec![
            (
                "dev-libs/newpkg".to_string(),
                PretendOutcome::New {
                    version: "1.0".to_string()
                }
            ),
            (
                "dev-libs/upgradepkg".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            ),
            (
                "dev-libs/withdeps".to_string(),
                PretendOutcome::New {
                    version: "1.0".to_string()
                }
            )
        ]
    );
}

/// Like `graph`, but with a specific `Deep` value.
fn graph_deep(atom_str: &str, deep: Deep) -> Vec<(String, PretendOutcome)> {
    let root = fixtures_root();
    ResolveRequest {
        deep,
        ..ResolveRequest::new(
            &root,
            &root,
            &[atom_str.to_string()],
            &test_config(),
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolving {atom_str} failed: {e}"))
    .entries
    .into_iter()
    .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
    .collect()
}

/// Like `graph_deep(atom, Deep::Unlimited)`, but with a
/// `--reinstall-atoms` set applied.
fn graph_deep_reinstall_atoms(
    atom_str: &str,
    reinstall_atoms: &[&str],
) -> Vec<(String, PretendOutcome)> {
    let root = fixtures_root();
    let ra: Vec<String> = reinstall_atoms.iter().map(|s| s.to_string()).collect();
    ResolveRequest {
        deep: Deep::Unlimited,
        reinstall_atoms: ra.to_vec(),
        ..ResolveRequest::new(
            &root,
            &root,
            &[atom_str.to_string()],
            &test_config(),
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolving {atom_str} failed: {e}"))
    .entries
    .into_iter()
    .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
    .collect()
}

#[test]
fn reinstall_atoms_forces_an_otherwise_already_installed_deep_dep_to_reinstall() {
    // deeppkg (installed) RDEPENDs deeppkg2 (installed) RDEPENDs
    // newpkg (New). Under `--deep` alone deeppkg2 resolves to
    // AlreadyInstalled (the CLI filters it from the merge list).
    // `--reinstall-atoms dev-libs/deeppkg2` rewrites just that one to
    // a bare Reinstall, exactly like a scoped --emptytree; deeppkg
    // stays AlreadyInstalled and newpkg stays New.
    let bare = PretendOutcome::Reinstall {
        version: "1.0".to_string(),
        changed_flags: Vec::new(),
        deps_changed: false,
        slot_changed: false,
        rebuilt_binary: false,
        new_repo: false,
        slot_operator_rebuild: false,
    };
    let plain = graph_deep("dev-libs/deeppkg", Deep::Unlimited);
    assert_eq!(
        plain
            .iter()
            .find(|(n, _)| n == "dev-libs/deeppkg2")
            .map(|(_, o)| o.clone()),
        Some(PretendOutcome::AlreadyInstalled {
            version: "1.0".to_string()
        })
    );

    let forced = graph_deep_reinstall_atoms("dev-libs/deeppkg", &["dev-libs/deeppkg2"]);
    assert_eq!(
        forced,
        vec![
            (
                "dev-libs/newpkg".to_string(),
                PretendOutcome::New {
                    version: "1.0".to_string()
                }
            ),
            ("dev-libs/deeppkg2".to_string(), bare),
            (
                "dev-libs/deeppkg".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            ),
        ]
    );
}

#[test]
fn reinstall_atoms_accepts_a_wildcard_atom() {
    let forced = graph_deep_reinstall_atoms("dev-libs/deeppkg", &["dev-libs/*"]);
    assert!(forced.iter().any(|(n, _)| n == "dev-libs/deeppkg2"));
}

/// `resolve_pretend_graph` for one atom with the `--rebuild-if-*`
/// flags set (and `--update` on, so `rebuildtrigger` upgrades).
#[allow(clippy::too_many_arguments, reason = "#336 Phase 5 worklist")]
#[allow(clippy::fn_params_excessive_bools, reason = "#336 Phase 5 worklist")]
fn graph_rebuild_if(
    atom_str: &str,
    unbuilt: bool,
    new_rev: bool,
    new_ver: bool,
    rebuild_exclude: &[&str],
    rebuild_ignore: &[&str],
) -> Vec<(String, PretendOutcome)> {
    let root = fixtures_root();
    let ex: Vec<String> = rebuild_exclude.iter().map(|s| s.to_string()).collect();
    let ig: Vec<String> = rebuild_ignore.iter().map(|s| s.to_string()).collect();
    ResolveRequest {
        update: true,
        rebuild_if_unbuilt: unbuilt,
        rebuild_if_new_rev: new_rev,
        rebuild_if_new_ver: new_ver,
        rebuild_exclude: ex.to_vec(),
        rebuild_ignore: ig.to_vec(),
        ..ResolveRequest::new(
            &root,
            &root,
            &[atom_str.to_string()],
            &test_config(),
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolving {atom_str} failed: {e}"))
    .entries
    .into_iter()
    .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
    .collect()
}

#[test]
fn rebuild_if_unbuilt_reinstalls_a_consumer_of_a_merged_build_dep() {
    // dev-libs/rebuildconsumer (installed) has a vdb DEPEND on
    // dev-libs/rebuildtrigger; `emerge -u rebuildtrigger` upgrades it
    // 1.0 -> 2.0. --rebuild-if-unbuilt then schedules rebuildconsumer
    // for a rebuild (it isn't otherwise in the graph at all).
    let g = graph_rebuild_if("dev-libs/rebuildtrigger", true, false, false, &[], &[]);
    assert!(
        g.iter().any(|(n, o)| n == "dev-libs/rebuildconsumer"
            && matches!(
                o,
                PretendOutcome::Reinstall {
                    slot_operator_rebuild: false,
                    ..
                }
            )),
        "{g:?}"
    );
}

#[test]
fn rebuild_if_new_ver_ignores_a_same_version_dep() {
    // rebuildnochange's best tree version equals the installed one.
    // Even forced to reinstall (--reinstall-atoms), that is not a
    // "new version"/"new revision" -> its consumer is NOT rebuilt
    // under --rebuild-if-new-ver / -new-rev.
    let root = fixtures_root();
    for (nr, nv) in [(true, false), (false, true)] {
        let g = ResolveRequest {
            reinstall_atoms: vec!["dev-libs/rebuildnochange".to_string()],
            rebuild_if_new_rev: nr,
            rebuild_if_new_ver: nv,
            ..ResolveRequest::new(
                &root,
                &root,
                &["dev-libs/rebuildnochange".to_string()],
                &test_config(),
                &fixtures_root().join("distfiles"),
            )
        }
        .resolve()
        .unwrap()
        .entries
        .into_iter()
        .map(|e| (format!("{}/{}", e.category, e.package), e.outcome))
        .collect::<Vec<_>>();
        assert!(
            g.iter().any(|(n, _)| n == "dev-libs/rebuildnochange"),
            "the dep itself should be forced into the graph: {g:?}"
        );
        assert!(
            !g.iter()
                .any(|(n, _)| n == "dev-libs/rebuildnochangeconsumer"),
            "no rebuild for a same-version dep: {g:?}"
        );
    }
}

#[test]
fn rebuild_exclude_and_ignore_suppress_the_rebuild() {
    // --rebuild-exclude matches the parent; --rebuild-ignore matches
    // the merged dep. Either one keeps rebuildconsumer out.
    let ex = graph_rebuild_if(
        "dev-libs/rebuildtrigger",
        true,
        false,
        false,
        &["dev-libs/rebuildconsumer"],
        &[],
    );
    assert!(!ex.iter().any(|(n, _)| n == "dev-libs/rebuildconsumer"));
    let ig = graph_rebuild_if(
        "dev-libs/rebuildtrigger",
        true,
        false,
        false,
        &[],
        &["dev-libs/rebuildtrigger"],
    );
    assert!(!ig.iter().any(|(n, _)| n == "dev-libs/rebuildconsumer"));
}

#[test]
fn dynamic_deps_picks_ebuild_vs_vdb_deps_for_an_already_installed_deep_walk() {
    // changeddepspkg (installed) has vdb RDEPEND=dev-libs/samepkg but
    // its current ebuild RDEPEND=dev-libs/newpkg. Kept from being a
    // Reinstall via --reinstall-atoms's opposite... just drive it as
    // AlreadyInstalled by NOT requesting a reinstall: resolve_pretend
    // in test_config keeps a directly-named installed atom as
    // AlreadyInstalled (selective=true here), so --deep recurses via
    // enqueue_dependencies.
    let root = fixtures_root();
    let call = |dynamic_deps: bool| -> Vec<String> {
        ResolveRequest {
            deep: Deep::Unlimited,
            dynamic_deps,
            ..ResolveRequest::new(
                &root,
                &root,
                &["dev-libs/changeddepspkg".to_string()],
                &test_config(),
                &fixtures_root().join("distfiles"),
            )
        }
        .resolve()
        .unwrap()
        .entries
        .into_iter()
        .map(|e| format!("{}/{}", e.category, e.package))
        .collect()
    };
    // dynamic (default): the current ebuild's RDEPEND -> newpkg (New).
    assert!(call(true).iter().any(|n| n == "dev-libs/newpkg"));
    // =n: the vdb RDEPEND -> samepkg (installed) -> newpkg not pulled.
    assert!(!call(false).iter().any(|n| n == "dev-libs/newpkg"));
}

#[test]
fn installed_dep_string_effective_is_the_live_ebuild_value() {
    // Backlog #25 S1b: the built-`:=` append is EAPI-gated exactly
    // like real (`FakeVartree._apply_dynamic_deps`). These two
    // fixtures' vdbs carry no `EAPI` file, so real reads the
    // installed EAPI as `"0"` (`vartree.py:1054-1055`) -- no
    // `slot_operator` support -- and the live value stands even
    // though the vdb carries a built binding. (Without the gate this
    // append broke both #24 pins, Phase 5 S1 S0.)
    // --dynamic-deps=n and Raw collapse to the vdb record;
    // the no-live-metadata arm is real's `_DynamicDepsNotApplicable`
    // fallback (raw + global moves, identity in fixtures).
    // Every live map below carries `EAPI`, like real's `portdb`
    // `aux_get` always does -- a missing live `EAPI` is unsupported
    // and takes the raw fallback (unreachable in real).
    let root = fixtures_root();
    let live_slotop: HashMap<String, String> = [
        ("RDEPEND".to_string(), "dev-libs/slotoptarget:=".to_string()),
        ("EAPI".to_string(), "8".to_string()),
    ]
    .into_iter()
    .collect();
    // slotopdepspkg's vdb RDEPEND is `dev-libs/slotoptarget:2=` --
    // the live value stands.
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "slotopdepspkg",
        "1.0",
        Some(&live_slotop),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "dev-libs/slotoptarget:=");

    // revdepslotconsumer's vdb RDEPEND is
    // `dev-libs/revdepslottarget:0/1=` -- built, but its vdb has no
    // `EAPI` file: Effective is the live value (empty here), never
    // the vdb binding.
    let live_empty: HashMap<String, String> = [("EAPI".to_string(), "8".to_string())]
        .into_iter()
        .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "revdepslotconsumer",
        "1.0",
        Some(&live_empty),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "");
    assert!(memo.contains_key(&(
        "dev-libs".to_string(),
        "revdepslotconsumer".to_string(),
        "1.0".to_string(),
        "RDEPEND".to_string()
    )));

    // The live value stands alone even when the vdb carries a built
    // binding for the same cp.
    let live_target: HashMap<String, String> = [
        (
            "RDEPEND".to_string(),
            "dev-libs/revdepslottarget:=".to_string(),
        ),
        ("EAPI".to_string(), "8".to_string()),
    ]
    .into_iter()
    .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "revdepslotconsumer",
        "1.0",
        Some(&live_target),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "dev-libs/revdepslottarget:=");

    // =n: the raw snapshot, byte-for-byte.
    let mut memo = HashMap::new();
    let raw = installed_dep_string(
        &root,
        false,
        false,
        "dev-libs",
        "revdepslotconsumer",
        "1.0",
        Some(&live_target),
        "RDEPEND",
        InstalledMetaLayer::Raw,
        &mut memo,
    );
    assert_eq!(raw, "dev-libs/revdepslottarget:0/1=");

    // Missing live metadata: raw record stands (global moves are
    // identity without `profiles/updates` commands).
    let mut memo = HashMap::new();
    let fallback = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "revdepslotconsumer",
        "1.0",
        None,
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(fallback, "dev-libs/revdepslottarget:0/1=");
}

#[test]
fn installed_dep_string_effective_appends_built_atoms_when_eapi_gated() {
    // Backlog #25 S1b: real `FakeVartree._apply_dynamic_deps`
    // (`lib/_emerge/FakeVartree.py:146-191`) on the hermetic r25
    // shape (findings/l0.md "## #25 S0 (2026-09-27)"): both vdb rows
    // carry `EAPI` files (`8`), so the recorded bound atoms append
    // to the live depstring -- `Depstring: dev-libs/r25lib:=
    // >=dev-libs/r25lib-1.0:0/1=` (`realC-debug.log:35-47`).
    let root = fixtures_root();
    // r25mid: live `dev-libs/r25lib:=`, vdb
    // `>=dev-libs/r25lib-1.0:0/1=` (real's recorded bound form).
    let live_mid: HashMap<String, String> = [
        ("RDEPEND".to_string(), "dev-libs/r25lib:=".to_string()),
        ("EAPI".to_string(), "8".to_string()),
    ]
    .into_iter()
    .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "r25mid",
        "1.0",
        Some(&live_mid),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "dev-libs/r25lib:= >=dev-libs/r25lib-1.0:0/1=");

    // r25consumer: live `<dev-libs/r25lib-2.0:=`, vdb
    // `<dev-libs/r25lib-2.0:0/1=`.
    let live_consumer: HashMap<String, String> = [
        ("RDEPEND".to_string(), "<dev-libs/r25lib-2.0:=".to_string()),
        ("EAPI".to_string(), "8".to_string()),
    ]
    .into_iter()
    .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "r25consumer",
        "1.0",
        Some(&live_consumer),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "<dev-libs/r25lib-2.0:= <dev-libs/r25lib-2.0:0/1=");

    // `--ignore-built-slot-operator-deps`: append suppressed, live
    // stands (real `FakeVartree.py:166-168`).
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        true,
        "dev-libs",
        "r25mid",
        "1.0",
        Some(&live_mid),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, "dev-libs/r25lib:=");

    // Live EAPI without `:=` support voids the whole overlay, not
    // just the append (real `FakeVartree.py:176-178`): the raw
    // record stands.
    let live_old_eapi: HashMap<String, String> = [
        ("RDEPEND".to_string(), "dev-libs/r25lib:=".to_string()),
        ("EAPI".to_string(), "4".to_string()),
    ]
    .into_iter()
    .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "r25mid",
        "1.0",
        Some(&live_old_eapi),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, ">=dev-libs/r25lib-1.0:0/1=");

    // Unsupported live EAPI: `_DynamicDepsNotApplicable`, raw stands
    // (real `FakeVartree.py:158-162`).
    let live_bad_eapi: HashMap<String, String> = [
        ("RDEPEND".to_string(), "dev-libs/r25lib:=".to_string()),
        ("EAPI".to_string(), "99".to_string()),
    ]
    .into_iter()
    .collect();
    let mut memo = HashMap::new();
    let eff = installed_dep_string(
        &root,
        true,
        false,
        "dev-libs",
        "r25mid",
        "1.0",
        Some(&live_bad_eapi),
        "RDEPEND",
        InstalledMetaLayer::Effective,
        &mut memo,
    );
    assert_eq!(eff, ">=dev-libs/r25lib-1.0:0/1=");
}

#[test]
fn default_dynamic_deps_walks_the_live_ebuild_alone() {
    // dev-libs/builtbindpkg is installed with vdb
    // RDEPEND="dev-libs/builtbindtarget:0/1=" while its current ebuild
    // RDEPEND is "dev-libs/newpkg" (the binding was dropped from the
    // tree). Its vdb carries no `EAPI` file, so real reads the
    // installed EAPI as `"0"` and the overlay never applies here
    // (backlog #25 S1b): the default walks the live ebuild alone;
    // `=n` walks the vdb snapshot alone;
    // `--ignore-built-slot-operator-deps` changes nothing on this
    // shape. (The EAPI-bearing r25 shape walks both; the ungated
    // append broke both #24 pins, Phase 5 S1 S0.)
    let root = fixtures_root();
    let call = |dynamic_deps: bool, ignore_built: bool| -> Vec<String> {
        ResolveRequest {
            deep: Deep::Unlimited,
            ignore_built_slot_operator_deps: ignore_built,
            dynamic_deps,
            ..ResolveRequest::new(
                &root,
                &root,
                &["dev-libs/builtbindpkg".to_string()],
                &test_config(),
                &fixtures_root().join("distfiles"),
            )
        }
        .resolve()
        .unwrap()
        .entries
        .into_iter()
        .map(|e| format!("{}/{}", e.category, e.package))
        .collect()
    };
    let default = call(true, false);
    assert!(
        default.iter().any(|n| n == "dev-libs/newpkg"),
        "live ebuild dep: {default:?}"
    );
    assert!(
        !default.iter().any(|n| n == "dev-libs/builtbindtarget"),
        "no append: the vdb-only binding is not walked: {default:?}"
    );
    let static_ = call(false, false);
    assert!(
        !static_.iter().any(|n| n == "dev-libs/newpkg"),
        "=n reads the vdb snapshot, not the ebuild: {static_:?}"
    );
    assert!(
        static_.iter().any(|n| n == "dev-libs/builtbindtarget"),
        "=n still walks the recorded built binding: {static_:?}"
    );
    let ignored = call(true, true);
    assert!(
        ignored.iter().any(|n| n == "dev-libs/newpkg"),
        "append suppressed, live dep intact: {ignored:?}"
    );
    assert!(
        !ignored.iter().any(|n| n == "dev-libs/builtbindtarget"),
        "ignore flag changes nothing here: {ignored:?}"
    );
}

#[test]
fn deep_walk_evaluates_flag_deps_against_the_installed_vdb_use_not_effective() {
    // dev-libs/deepvdbusepkg is installed with vdb USE="" (no
    // `wantdep`); its IUSE is `wantdep` and fixtures/repo/profiles/
    // base/package.use enables it in the *effective* set. Its current
    // ebuild RDEPENDs `wantdep? ( dev-libs/deepvdbusetarget )`.
    // Reached only via the --deep recursion under
    // dev-libs/deepvdbuseconsumer (New), that conditional must be
    // evaluated against the recorded vdb USE (real `_pkg_use_enabled`
    // for a built package) -> deepvdbusetarget NOT pulled.
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let names: Vec<String> = ResolveRequest {
        deep: Deep::Unlimited,
        ..ResolveRequest::new(
            &root,
            &root,
            &["dev-libs/deepvdbuseconsumer".to_string()],
            &config,
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap()
    .entries
    .into_iter()
    .map(|e| format!("{}/{}", e.category, e.package))
    .collect();
    assert!(
        names.iter().any(|n| n == "dev-libs/deepvdbuseconsumer"),
        "{names:?}"
    );
    assert!(
        !names.iter().any(|n| n == "dev-libs/deepvdbusetarget"),
        "vdb USE lacks `wantdep`, so the gated dep must not be walked: {names:?}"
    );
}

/// Resolve one consumer atom through the `--deep` walk and return
/// `(cat/pkg, outcome-variant, targets_running_root)` per graph entry
/// -- the shared probe for the `#132`/`#133` arm tests below (one
/// place holds the long `resolve_pretend_graph` argument list, copied
/// from the sibling test above). `root_deps` passes the fixture root
/// itself as the running root (the unit-level counterpart of the
/// contract suite's `PORTAGE_RUNNING_ROOT=$ROOT` pin).
fn resolve_deep_consumer(atom: &str, root_deps: bool) -> Vec<(String, String, bool)> {
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let running_root = root.clone();
    ResolveRequest {
        deep: Deep::Unlimited,
        root_deps_running_root: (if root_deps {
            Some(running_root.as_path())
        } else {
            None
        })
        .map(std::path::Path::to_path_buf),
        ..ResolveRequest::new(
            &root,
            &root,
            &[atom.to_string()],
            &config,
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap()
    .entries
    .into_iter()
    .map(|e| {
        let outcome = match &e.outcome {
            PretendOutcome::NoVisibleCandidate => "NoVisibleCandidate",
            PretendOutcome::New { .. } => "New",
            PretendOutcome::Upgrade { .. } => "Upgrade",
            PretendOutcome::Downgrade { .. } => "Downgrade",
            PretendOutcome::AlreadyInstalled { .. } => "AlreadyInstalled",
            PretendOutcome::Reinstall { .. } => "Reinstall",
            PretendOutcome::Uninstall { .. } => "Uninstall",
        };
        (
            format!("{}/{}", e.category, e.package),
            outcome.to_string(),
            e.targets_running_root,
        )
    })
    .collect()
}

#[test]
fn deep_walk_evaluates_conditional_use_deps_of_installed_parents() {
    // #139 (#132's missing Rust-side test): the `deepusedep*` arms
    // pin `enqueue_dependencies`' evaluation rule at the graph level.
    // Each installed parent carries `~child-1.0[flip=]`; the token is
    // evaluated against the parent's recorded vdb USE (real
    // `_pkg_use_enabled` for a built package) before candidate
    // selection, so the conditional form never arrives unevaluated
    // (where it imposes no state constraint at all).
    //
    // Arm A (parent built -flip, child installed +flip and
    // profile-pinned +flip): `[-flip]` is unsatisfiable -- the child
    // is present as an entry but never as a satisfied install, so the
    // abort path (pinned at the CLI by the #132 contract test) has
    // something to report.
    let arm_a = resolve_deep_consumer("dev-libs/deepusedepconsumer", false);
    assert!(
        arm_a
            .iter()
            .any(|(n, _, _)| n == "dev-libs/deepusedepconsumer"),
        "{arm_a:?}"
    );
    assert!(
        arm_a
            .iter()
            .any(|(n, _, _)| n == "dev-libs/deepusedepchild"),
        "evaluated [-flip] is not satisfied by the installed +flip child, \
         so the child must surface (unsatisfied), not vanish: {arm_a:?}"
    );
    assert!(
        !arm_a
            .iter()
            .any(|(n, o, _)| n == "dev-libs/deepusedepchild"
                && (o == "AlreadyInstalled" || o == "New")),
        "the +flip instance satisfies neither [-flip] nor a fresh build \
         under the profile pin: {arm_a:?}"
    );
    //
    // Arm B (same parent shape, child not profile-pinned): `[-flip]`
    // reaches candidate *selection* -- the child rebuilds with flip
    // off rather than aborting. A fix that only hardened the failure
    // display would pass arm A and fail here.
    let arm_b = resolve_deep_consumer("dev-libs/deepusedepbconsumer", false);
    assert!(
        arm_b
            .iter()
            .any(|(n, o, _)| n == "dev-libs/deepusedepbchild" && o == "Reinstall"),
        "evaluated [-flip] must rebuild the installed +flip child with \
         flip off: {arm_b:?}"
    );
    //
    // Arm C (control -- parent built +flip): the same atom evaluates
    // to `[flip]`, which the installed +flip child satisfies, so
    // nothing merges. (The graph still records the walked installed
    // nodes as `AlreadyInstalled` entries -- unlike the CLI merge
    // list -- so the assertion is "no merging entry", not
    // single-entry.) Guards against an over-broad fix.
    let arm_c = resolve_deep_consumer("dev-libs/deepusedepokconsumer", false);
    assert!(
        arm_c
            .iter()
            .any(|(n, o, _)| n == "dev-libs/deepusedepokconsumer" && o == "New"),
        "{arm_c:?}"
    );
    assert!(
        !arm_c
            .iter()
            .any(|(_, o, _)| o != "New" && o != "AlreadyInstalled"),
        "control: a satisfied evaluated dep merges nothing: {arm_c:?}"
    );
}

#[test]
fn root_deps_walk_evaluates_conditional_use_deps_before_the_satisfied_check() {
    // #133 at the graph level (the contract pin is
    // `test_root_deps_evaluates_conditional_use_deps_before_the_satisfied_check`):
    // `dev-libs/deeprootdepparent` is installed with vdb USE=""
    // (built -flip) and BDEPENDs `~dev-libs/deeprootdepchild-1.0[flip=]`;
    // the running root has the child installed +flip. With `--root-deps`
    // the producers must evaluate the atom to `[-flip]` *and* enforce it
    // against the running-root instance -- otherwise the raw form is
    // vacuously satisfied and the child vanishes (bed
    // `l0-fx-20260922T082944Z`: real rebuilds it with flip off).
    let with_root_deps = resolve_deep_consumer("dev-libs/deeprootdepconsumer", true);
    assert!(
        with_root_deps
            .iter()
            .any(|(n, o, running)| n == "dev-libs/deeprootdepchild"
                && o == "Reinstall"
                && *running),
        "evaluated [-flip] is not satisfied by the running root's +flip \
         child, so it resolves as a running-root rebuild: {with_root_deps:?}"
    );
    //
    // Control without `--root-deps`: the producers are a strict no-op
    // (`root_deps_running_root` None) and the ordinary S5-evaluated
    // walk rebuilds the child against the target root instead.
    let without = resolve_deep_consumer("dev-libs/deeprootdepconsumer", false);
    assert!(
        without
            .iter()
            .any(|(n, o, running)| n == "dev-libs/deeprootdepchild"
                && o == "Reinstall"
                && !*running),
        "control: without --root-deps the same rebuild targets ROOT: {without:?}"
    );
}

/// #141 (Phase 5b S1): a `--root-deps` running-root build entry's
/// `use_flags_display` must carry the rebuild's flipped flag, so the
/// renderer prints real's `USE="-flip*"` column (bed
/// `l0-fx-20260922T192350Z`) instead of skipping the display. The
/// contract pin is
/// `test_root_deps_evaluates_conditional_use_deps_before_the_satisfied_check`;
/// this is the `cargo test` gate over the same constructor.
#[test]
fn root_deps_build_entry_displays_the_rebuild_use_column() {
    let root = fixtures_root();
    let config = test_config();
    let entries = ResolveRequest {
        deep: Deep::Unlimited,
        root_deps_running_root: Some(root.to_path_buf()),
        ..ResolveRequest::new(
            &root,
            &root,
            &["dev-libs/deeprootdepconsumer".to_string()],
            &config,
            &fixtures_root().join("distfiles"),
        )
    }
    .resolve()
    .unwrap_or_else(|e| panic!("resolve_pretend_graph failed: {e}"))
    .entries;

    let child = entries
        .iter()
        .find(|e| e.package == "deeprootdepchild")
        .expect("the running-root rebuild entry is present");
    assert!(
        child.targets_running_root,
        "the rebuild is the running-root build entry: {child:?}"
    );
    // Installed +flip (vdb USE="flip"), rebuilt with flip off -- the
    // `use_flags_display` pair the renderer's `-flip*` comes from.
    assert_eq!(
        child.use_flags_display,
        vec![("flip".to_string(), false)],
        "the rebuild's flipped flag must reach the display (#141)"
    );
    assert_eq!(child.slot.as_deref(), Some("0"));
}

