#[test]
fn complete_graph_never_merges_a_missing_deep_dep_of_an_installed_pkg() {
    // deeppkg (installed) -> RDEPEND deeppkg2 (installed) -> RDEPEND
    // newpkg (not installed). `-D` deep-walks and merges newpkg.
    // Real `complete` mode (`_complete_graph` 8662) also deep-walks
    // but swaps to `_select_pkg_from_graph` -- graph-or-installed,
    // never a new merge -- so the CLI's 2-pass (phase 1 non-complete,
    // phase 2 complete with phase 1's merge set locked) leaves newpkg
    // accounted-for but unmerged. The low-level `complete=true` with
    // no locked set is the pre-2-pass fallback: a plain deep walk.
    let root = fixtures_root();
    #[allow(clippy::too_many_arguments, reason = "#336 Phase 5 worklist")]
    let resolve_cfg =
        |atom: &str, update: bool, deep: Deep, complete: bool, locked: &[&str]| -> GraphResult {
            let mut cfg = test_config();
            cfg.complete_locked_merges = locked.iter().map(|s| s.to_string()).collect();
            ResolveRequest {
                update,
                deep,
                complete,
                ..ResolveRequest::new(
                    &root,
                    &root,
                    &[atom.to_string()],
                    &cfg,
                    &fixtures_root().join("distfiles"),
                )
            }
            .resolve()
            .unwrap_or_else(|e| panic!("resolving {atom} failed: {e}"))
        };
    let resolve = |atom: &str, update: bool, deep: Deep, complete: bool| -> GraphResult {
        resolve_cfg(atom, update, deep, complete, &[])
    };
    let names = |r: &GraphResult| -> Vec<String> {
        r.entries
            .iter()
            .map(|e| format!("{}/{}", e.category, e.package))
            .collect()
    };
    let has_newpkg = |r: &GraphResult| names(r).iter().any(|n| n == "dev-libs/newpkg");

    // complete=false, no --deep: deeppkg's deps are not walked.
    assert!(!has_newpkg(&resolve(
        "dev-libs/deeppkg",
        false,
        Deep::NotRequested,
        false
    )));
    // `-D` deep-walks and merges the missing dep.
    assert!(has_newpkg(&resolve(
        "dev-libs/deeppkg",
        false,
        Deep::Unlimited,
        false
    )));
    // `complete=true` never merges the missing deep dep -- neither
    // the low-level call (no locked set) nor the CLI's real 2-pass
    // (phase 1's merge set locked). Real `_select_pkg_from_graph`:
    // graph-or-installed, never a new merge. And -- unlike `-D` --
    // complete mode doesn't force the deep walk at all unless
    // `--changed-deps-report` needs the wider scan (portuale's deep
    // walk is full resolution per node, far heavier than real's).
    assert!(!has_newpkg(&resolve(
        "dev-libs/deeppkg",
        false,
        Deep::NotRequested,
        true
    )));
    assert!(!has_newpkg(&resolve_cfg(
        "dev-libs/deeppkg",
        false,
        Deep::NotRequested,
        true,
        &["dev-libs/deeppkg"],
    )));

    // Auto-enable: `emerge -u completegraphpkg` is an Upgrade (a
    // version change), so `complete_graph_auto_enable` says to re-walk
    // when `complete_if_new_ver` is on -- but not when every trigger
    // is off.
    let up = resolve("dev-libs/completegraphpkg", true, Deep::NotRequested, false);
    assert!(matches!(
        up.entries
            .iter()
            .find(|e| e.package == "completegraphpkg")
            .map(|e| &e.outcome),
        Some(PretendOutcome::Upgrade { .. })
    ));
    assert!(!has_newpkg(&up));
    assert!(complete_graph_auto_enable(
        &up.entries,
        true,
        true,
        true,
        std::path::Path::new(""),
        &[],
        &portage_profile::Config::default()
    ));
    assert!(complete_graph_auto_enable(
        &up.entries,
        false,
        true,
        false,
        std::path::Path::new(""),
        &[],
        &portage_profile::Config::default()
    ));
    assert!(!complete_graph_auto_enable(
        &up.entries,
        true,
        false,
        true,
        std::path::Path::new(""),
        &[],
        &portage_profile::Config::default()
    ));
    assert!(!complete_graph_auto_enable(
        &up.entries,
        false,
        false,
        false,
        std::path::Path::new(""),
        &[],
        &portage_profile::Config::default()
    ));
    // Even after the auto-enable re-walk, the missing deep dep is not
    // merged (2-pass, `completegraphpkg` is the only phase-1 merge).
    assert!(!has_newpkg(&resolve_cfg(
        "dev-libs/completegraphpkg",
        true,
        Deep::NotRequested,
        true,
        &["dev-libs/completegraphpkg"],
    )));

    // An AlreadyInstalled-only graph never auto-enables.
    let noop = resolve("dev-libs/deeppkg2", false, Deep::NotRequested, false);
    assert!(!complete_graph_auto_enable(
        &noop.entries,
        true,
        true,
        true,
        std::path::Path::new(""),
        &[],
        &portage_profile::Config::default()
    ));
}

/// Like `graph_deep`, but driven by `--emptytree`/`-e` instead
/// (`deep` forced on, every installed atom -> a bare Reinstall).
fn graph_empty(atom_str: &str) -> Vec<(String, PretendOutcome)> {
    graph_with(atom_str, |r| r.empty = true)
}

#[test]
fn emptytree_reinstalls_the_whole_deep_dependency_tree() {
    // Without --deep/--emptytree, `graph("dev-libs/deeppkg")` on an
    // installed deeppkg shows only itself (AlreadyInstalled, or a
    // top-level bare Reinstall) and never walks deeppkg2/newpkg.
    // --emptytree forces `deep` on AND turns each installed dep into
    // a Reinstall, so the whole chain shows: deeppkg + deeppkg2 as
    // Reinstall (both installed), newpkg as New (not installed).
    let entries = graph_empty("dev-libs/deeppkg");
    let bare = PretendOutcome::Reinstall {
        version: "1.0".to_string(),
        changed_flags: vec![],
        deps_changed: false,
        slot_changed: false,
        rebuilt_binary: false,
        new_repo: false,
        slot_operator_rebuild: false,
    };
    assert_eq!(
        entries,
        vec![
            (
                "dev-libs/newpkg".to_string(),
                PretendOutcome::New {
                    version: "1.0".to_string()
                }
            ),
            ("dev-libs/deeppkg2".to_string(), bare.clone()),
            ("dev-libs/deeppkg".to_string(), bare)
        ]
    );
}

#[test]
fn deep_not_requested_never_walks_an_already_installed_packages_own_dependencies() {
    // dev-libs/deeppkg is already installed and stays AlreadyInstalled
    // (no --update); its own RDEPEND chain (-> deeppkg2 -> newpkg) is
    // never read at all without --deep, matching real portage's own
    // default (deep=0, permanently "too deep" at every depth -- see
    // `Deep::NotRequested`'s own doc comment).
    assert_eq!(
        graph_deep("dev-libs/deeppkg", Deep::NotRequested),
        vec![(
            "dev-libs/deeppkg".to_string(),
            PretendOutcome::AlreadyInstalled {
                version: "1.0".to_string()
            }
        )]
    );
}

#[test]
fn deep_unlimited_walks_the_whole_already_installed_chain() {
    // Bare --deep: unlimited depth, so both already-installed steps
    // (deeppkg -> deeppkg2) get walked, reaching deeppkg2's own
    // RDEPEND on newpkg (New).
    assert_eq!(
        graph_deep("dev-libs/deeppkg", Deep::Unlimited),
        vec![
            (
                "dev-libs/newpkg".to_string(),
                PretendOutcome::New {
                    version: "1.0".to_string()
                }
            ),
            (
                "dev-libs/deeppkg2".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            ),
            (
                "dev-libs/deeppkg".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            )
        ]
    );
}

#[test]
fn deep_bounded_one_walks_exactly_one_level_of_already_installed_packages() {
    // --deep=1: deeppkg (depth 0) recurses since 0 < 1, discovering
    // deeppkg2 at depth 1 -- but deeppkg2 itself does NOT recurse
    // (1 < 1 is false), so newpkg is never reached.
    assert_eq!(
        graph_deep("dev-libs/deeppkg", Deep::Bounded(1)),
        vec![
            (
                "dev-libs/deeppkg2".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            ),
            (
                "dev-libs/deeppkg".to_string(),
                PretendOutcome::AlreadyInstalled {
                    version: "1.0".to_string()
                }
            )
        ]
    );
}

