#[test]
fn mixed_priority_cycle_reports_per_edge_labels() {
    // Backlog #228: `dev-libs/slopcyca -RDEPEND:=-> dev-libs/slopcycb
    // -DEPEND-> dev-libs/slopcyca`. The `RDEPEND` `:=` edge is an
    // unsatisfied `runtime_slot_op` priority -- unbreakable at every
    // `ignore_priority` rung, so real aborts (n228 probe: real
    // 3.0.81.3 rc 1 with `(buildtime)` on the back edge and
    // `(runtime_slot_op)` on the slot-op edge) where the pre-#228
    // detector saw only a soft run-time edge and merged silently.
    // Since backlog #278 the rotation starts where real's
    // `shortest_cycle[0]` starts (`slopcycb`: fresh 3.0.82.2 probe
    // prints `slopcycb depends on / slopcyca (buildtime) / slopcycb
    // (runtime_slot_op)`), so the labels read `buildtime` into the
    // second line, `runtime_slot_op` closing.
    let result = graph_result_real("dev-libs/slopcyca");
    assert_eq!(
        result.circular_deps,
        vec![vec![
            "dev-libs/slopcycb-1.0".to_string(),
            "dev-libs/slopcyca-1.0".to_string()
        ]]
    );
    assert_eq!(
        cycle_edge_labels(&result.entries, &result.circular_deps[0]),
        vec!["buildtime".to_string(), "runtime_slot_op".to_string()]
    );
    // The all-buildtime fixtures keep the old rendering: every
    // edge labels `(buildtime)`.
    let hard = graph_result_real("dev-libs/hardcyclea");
    assert_eq!(
        cycle_edge_labels(&hard.entries, &hard.circular_deps[0]),
        vec!["buildtime".to_string(), "buildtime".to_string()]
    );
}

#[test]
fn conditional_grandparent_with_undeclared_flag_is_masked_invalid_before_any_cycle_analysis() {
    // Backlog #153: the fucyclea/fucycleb USE-gated cycle is still in
    // the tree, but the top-level target dev-libs/fucyclec constrains
    // the solution flag conditionally (`dev-libs/fucyclea[x?]`) with
    // `x` in no IUSE of its own -- real masks the whole candidate
    // `invalid` at construction (`Package._validate_deps`), so the
    // resolve fails with the all-masked report before any cycle is
    // ever walked: there is no circular-dep suggestion to keep. (This
    // test previously pinned the followup suggestion; that output
    // described a merge real never makes.)
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let err = ResolveRequest::new(
        &root,
        &root,
        &["dev-libs/fucyclec".to_string()],
        &config,
        &fixtures_root().join("distfiles"),
    )
    .resolve()
    .expect_err("fucyclec must fail: its only candidate is masked invalid");
    let Error::Detail(report) = err else {
        panic!("expected the all-masked report, got: {err:?}");
    };
    assert!(
        report.contains(
            "- dev-libs/fucyclec-1.0::testrepo (masked by: invalid: DEPEND: \
             USE flag 'x' referenced in conditional 'x?' in atom \
             'dev-libs/fucyclea[x?]' is not in IUSE)"
        ),
        "{report}"
    );
}

#[test]
fn record_slot_conflict_merges_same_triple_and_appends_new() {
    // Real keeps one collision handler per conflicting slot: a second
    // distinct atom hitting the same (slot, existing, current) triple
    // re-renders the record (rebuilt from the live pullers) instead
    // of appending a duplicate notice block.
    let mk = |atom: &str, current: &str| SlotConflict {
        category: "dev-libs".to_string(),
        package: "t".to_string(),
        slot: "0".to_string(),
        resolved_version: "2.0".to_string(),
        conflicting_atom: atom.to_string(),
        instances: vec![
            SlotConflictInstance {
                version: "2.0".to_string(),
                sub_slot: "0".to_string(),
                repo_name: "r".to_string(),
                use_display: Vec::new(),
                parents: Vec::new(),
                installed: false,
            },
            SlotConflictInstance {
                version: current.to_string(),
                sub_slot: "0".to_string(),
                repo_name: "r".to_string(),
                use_display: Vec::new(),
                parents: Vec::new(),
                installed: false,
            },
        ],
    };
    let mut v = vec![mk("atom-1", "1.0")];
    record_slot_conflict(&mut v, mk("atom-2", "1.0"));
    assert_eq!(v.len(), 1);
    assert_eq!(v[0].conflicting_atom, "atom-2");
    record_slot_conflict(&mut v, mk("atom-3", "1.5"));
    assert_eq!(v.len(), 2);
}

#[test]
fn large_cycle_count_and_display_fire_on_a_four_ring() {
    // dev-libs/cyc4a through dev-libs/cyc4d form a four-ring of
    // build-time deps (the cyc4a edge gated behind USE=x, on by
    // default): real `get_cycles` records one ring per node, so four
    // records trip `large_cycle_count`, and the stuck remainder
    // re-displays all four members in leaf-drain order.
    let result = graph_result_real("dev-libs/cyc4a");
    assert_eq!(result.circular_deps.len(), 1);
    assert!(
        result.large_cycle_count,
        "four rotations must trip the trailer"
    );
    let mut display = result.cycle_display.clone();
    display.sort();
    assert_eq!(
        display,
        vec![
            "dev-libs/cyc4a-1.0".to_string(),
            "dev-libs/cyc4b-1.0".to_string(),
            "dev-libs/cyc4c-1.0".to_string(),
            "dev-libs/cyc4d-1.0".to_string(),
        ]
    );
}

#[test]
fn small_cycles_report_without_large_count_or_display() {
    // Control: the two-ring reports its error block but neither the
    // trailer (two records) nor ... -- well, the re-display still
    // shows (two members); only `large_cycle_count` stays false.
    let result = graph_result_real("dev-libs/hardcyclea");
    assert_eq!(result.circular_deps.len(), 1);
    assert!(
        !result.large_cycle_count,
        "two rotations must not trip the trailer"
    );
    assert_eq!(result.cycle_display.len(), 2);
}

#[test]
fn masked_candidates_for_atom_reports_masked_only_matches() {
    // Real `_show_unsatisfied_dep`'s version match: the masked list
    // fires when every version-matching ebuild is masked, and stays
    // silent when something is visible or nothing matches at all.
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("repos");
    let masked = masked_candidates_for_atom(&repos, "dev-libs/maskeddep", &config)
        .expect("package.mask'd dep discloses");
    assert_eq!(
        masked,
        vec![(
            "dev-libs/maskeddep-1.0::testrepo".to_string(),
            vec!["package.mask".to_string()]
        )]
    );
    let kw = masked_candidates_for_atom(&repos, "dev-libs/kwmaskeddep", &config)
        .expect("keyword-masked dep discloses");
    assert_eq!(
        kw,
        vec![(
            "dev-libs/kwmaskeddep-1.0::testrepo".to_string(),
            vec!["~amd64 keyword".to_string()]
        )]
    );
    // A visible candidate silences the report (USE-mismatch-only and
    // friends take real's other paths).
    assert_eq!(
        masked_candidates_for_atom(&repos, "dev-libs/newpkg", &config),
        None
    );
    // Nothing matching by version at all: real's plain "no ebuilds"
    // case, also silent here.
    assert_eq!(
        masked_candidates_for_atom(&repos, "dev-libs/doesnotexist-anywhere", &config),
        None
    );
}

#[test]
fn invalid_use_conditional_mask_matches_portage_on_all_three_fixture_cases() {
    // Backlog #153: real 3.0.82.2 masks all three `invalid` (oracles
    // captured against a `cp -a` copy of this same tree) --
    // `fucyclec` (atom `[x?]` in DEPEND), `usedeppkg` (atom
    // `[baz(+)?]` in RDEPEND -- a defaulted conditional is still
    // validated), `somercurial` (`soflag? ( … )` group in RDEPEND).
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("repos");
    for (cat, pkg, version, expected) in [
        (
            "dev-libs",
            "fucyclec",
            "1.0",
            "invalid: DEPEND: USE flag 'x' referenced in conditional 'x?' in atom 'dev-libs/fucyclea[x?]' is not in IUSE",
        ),
        (
            "dev-libs",
            "usedeppkg",
            "1.0",
            "invalid: RDEPEND: USE flag 'baz' referenced in conditional 'baz?' in atom 'dev-libs/multislotpkg:1[baz(+)?]' is not in IUSE",
        ),
        (
            "dev-vcs",
            "somercurial",
            "5.5.1",
            "invalid: RDEPEND: USE flag 'soflag' referenced in conditional 'soflag?' is not in IUSE",
        ),
    ] {
        let candidates = list_candidates(&repos, cat, pkg).expect("list_candidates");
        let c = candidates
            .iter()
            .find(|c| c.version == version)
            .expect("fixture version");
        assert_eq!(
            invalid_use_conditional_reasons(c, cat, pkg, &config),
            vec![expected.to_string()],
            "{cat}/{pkg}"
        );
        assert!(!is_visible(c, cat, pkg, &config), "{cat}/{pkg}");
    }
    // Negative control: `gpcyclea` conditions on `x` with `IUSE="+x"`.
    let gpl = list_candidates(&repos, "dev-libs", "gpcyclea").expect("list_candidates");
    let g = gpl.iter().find(|c| c.version == "1.0").expect("version");
    assert!(invalid_use_conditional_reasons(g, "dev-libs", "gpcyclea", &config).is_empty());
    assert!(is_visible(g, "dev-libs", "gpcyclea", &config));
    // End to end: the masked-candidates disclosure carries the reason.
    let masked = masked_candidates_for_atom(&repos, "dev-libs/fucyclec", &config)
        .expect("invalid dep discloses");
    assert_eq!(
        masked,
        vec![(
            "dev-libs/fucyclec-1.0::testrepo".to_string(),
            vec!["invalid: DEPEND: USE flag 'x' referenced in conditional 'x?' in atom 'dev-libs/fucyclea[x?]' is not in IUSE".to_string()]
        )]
    );
}

#[test]
fn first_invalid_conditional_covers_forms_nesting_and_order() {
    let valid: HashSet<String> = ["x".to_string()].into_iter().collect();
    // Clean strings pass, whatever the form.
    for dep in [
        "dev-libs/a[x?] dev-libs/b",
        "x? ( dev-libs/a )",
        "dev-libs/a[!x?] dev-libs/b[x=]",
        "|| ( dev-libs/a dev-libs/b )",
        "dev-libs/a[x(+)?]",
    ] {
        assert_eq!(first_invalid_conditional(dep, &valid), None, "{dep}");
    }
    // Every conditional form reports with real's conditional text.
    for (dep, msg) in [
        (
            "dev-libs/a[y?]",
            "USE flag 'y' referenced in conditional 'y?' in atom 'dev-libs/a[y?]' is not in IUSE",
        ),
        (
            "dev-libs/a[!y?]",
            "USE flag 'y' referenced in conditional '!y?' in atom 'dev-libs/a[!y?]' is not in IUSE",
        ),
        (
            "dev-libs/a[y=]",
            "USE flag 'y' referenced in conditional 'y=' in atom 'dev-libs/a[y=]' is not in IUSE",
        ),
        (
            "dev-libs/a[!y=]",
            "USE flag 'y' referenced in conditional '!y=' in atom 'dev-libs/a[!y=]' is not in IUSE",
        ),
        (
            "y? ( dev-libs/a )",
            "USE flag 'y' referenced in conditional 'y?' is not in IUSE",
        ),
        (
            "!y? ( dev-libs/a )",
            "USE flag 'y' referenced in conditional '!y?' is not in IUSE",
        ),
    ] {
        assert_eq!(
            first_invalid_conditional(dep, &valid).as_deref(),
            Some(msg),
            "{dep}"
        );
    }
    // Encounter order: an atom before a group reports the atom (real
    // validates each token as scanned, groups at their `)` close).
    assert_eq!(
        first_invalid_conditional("dev-libs/a[y?] z? ( dev-libs/b )", &valid).as_deref(),
        Some("USE flag 'y' referenced in conditional 'y?' in atom 'dev-libs/a[y?]' is not in IUSE")
    );
    assert_eq!(
        first_invalid_conditional("z? ( dev-libs/b ) dev-libs/a[y?]", &valid).as_deref(),
        Some("USE flag 'z' referenced in conditional 'z?' is not in IUSE")
    );
    // Nested groups validate innermost first.
    assert_eq!(
        first_invalid_conditional("z? ( y? ( dev-libs/b ) )", &valid).as_deref(),
        Some("USE flag 'y' referenced in conditional 'y?' is not in IUSE")
    );
}

