/// Backlog #129 (S1): real's two notices on the mg2top backtrack
/// shape (`l0-fx-20260927T080515Z` oracle) come from the settled
/// backtrack trial state, not from a second pass. The search
/// settles every `-1`, and the accumulated masks derive the
/// slot-conflict `WARNING` rows (`mgxc-2` vs `=mgxc-1`/`mgxa-1`,
/// `mgfc-3.0` vs `=mgfc-1`/`mgfa-1`, in first-mask order) plus the
/// abbreviated missing-dependency slots (`mgxb:0`, `mgfb:0`).
#[test]
fn backtrack_missed_updates_reports_the_mg2top_shape() {
    let result = graph_result_real_backtrack("dev-libs/mg2top", 20);
    assert!(
        result.slot_conflicts.is_empty(),
        "the search settles with no surviving conflict"
    );
    let versions: Vec<(&str, &str)> = result
        .entries
        .iter()
        .filter_map(|e| merge_bound_version(&e.outcome).map(|v| (e.package.as_str(), v.as_str())))
        .collect();
    for pkg in ["mg2top", "mgfa", "mgfb", "mgfc", "mgxa", "mgxb", "mgxc"] {
        assert!(
            versions.iter().any(|(p, v)| p == &pkg && v == &"1"),
            "settles {pkg}-1, saw {versions:?}"
        );
    }
    assert_eq!(
        result
            .skipped_updates
            .iter()
            .map(|s| (
                s.package.as_str(),
                s.skipped_version.as_str(),
                s.atom.as_str(),
                s.consumer_cpv.as_str()
            ))
            .collect::<Vec<_>>(),
        vec![
            (
                "mgxc",
                "2",
                "=dev-libs/mgxc-1",
                "dev-libs/mgxa-1:0/0::testrepo"
            ),
            (
                "mgfc",
                "3.0",
                "=dev-libs/mgfc-1",
                "dev-libs/mgfa-1:0/0::testrepo"
            ),
        ]
    );
    assert_eq!(
        result
            .skipped_missing_deps
            .iter()
            .map(|s| (s.category.as_str(), s.package.as_str(), s.slot.as_str()))
            .collect::<Vec<_>>(),
        vec![("dev-libs", "mgxb", "0"), ("dev-libs", "mgfb", "0"),]
    );
}

/// Backlog #129 (S1): the missed-update derivation only runs on a
/// clean settle. At `--backtrack=0` the mg2top root pass keeps its
/// slot conflicts (highest-first picks the `-2`s), so no mask
/// trial state exists and neither notice may fire.
#[test]
fn backtrack_missed_updates_stays_silent_without_a_clean_settle() {
    let result = graph_result_real_backtrack("dev-libs/mg2top", 0);
    assert!(
        !result.slot_conflicts.is_empty(),
        "bt0 keeps the conflicts instead of settling"
    );
    assert!(
        result.skipped_updates.is_empty(),
        "no WARNING rows without trial state: {:?}",
        result.skipped_updates
    );
    assert!(
        result.skipped_missing_deps.is_empty(),
        "no abbreviated slots without trial state: {:?}",
        result.skipped_missing_deps
    );
}

/// Backlog #242 Slice D: `skipped_update_roots` attributes the missed
/// instance to the root the rejecting parent's edge points at, and a
/// merge parent to its entry's root. The blk0 shape: target `blk0b-1`
/// rejects `blk0x-3` through its `DEPEND` edge while a running-rooted
/// twin of the graph exists (cross-active) — the miss lands running,
/// the parent stays target. Single-rooted (no running entry anywhere)
/// the same edges attribute target — the `fixture_env` shape.
#[test]
fn skipped_update_roots_attributes_miss_and_parent_per_edge() {
    fn entry(package: &str, version: &str, running: bool, deps: Vec<DepEdge>) -> GraphEntry {
        GraphEntry {
            discovery: 0,
            category: "dev-libs".to_string(),
            package: package.to_string(),
            outcome: PretendOutcome::New {
                version: version.to_string(),
            },
            blockers: Vec::new(),
            slot: Some("0".to_string()),
            sub_slot: Some("0".to_string()),
            repo_name: Some("testrepo".to_string()),
            oldbest: Vec::new(),
            use_flags_display: Vec::new(),
            use_expand_display: Vec::new(),
            use_expand_display_p: Vec::new(),
            keyword_mask: None,
            new_slot: false,
            interactive: false,
            fetch_restrict: false,
            fetch_restrict_satisfied: false,
            download_files: Vec::new(),
            required_by: Vec::new(),
            source: CandidateSource::Ebuild,
            provenance: VisibilityProvenance::default(),
            keyword_suggestion: None,
            use_suggestion: None,
            parent_use_suggestion: None,
            targets_running_root: running,
            remote_binary: false,
            build_id: None,
            deps,
        }
    }
    fn edge(child: &str, atom: &str, key: u8) -> DepEdge {
        DepEdge {
            atom: atom.to_string(),
            evaluated: atom.to_string(),
            category: "dev-libs".to_string(),
            package: child.to_string(),
            priority: DepPriority::default(),
            disjunctive: false,
            alt: None,
            key,
        }
    }
    // Cross-active: a target parent with a DEPEND edge at the miss
    // plus a running entry elsewhere in the graph.
    let running_twin = entry("blk0x", "1", true, Vec::new());
    let parent = entry(
        "blk0b",
        "1",
        false,
        vec![edge("blk0x", "<dev-libs/blk0x-2", 3)],
    );
    let entries = vec![running_twin, parent];
    assert_eq!(
        skipped_update_roots(
            &entries,
            ("dev-libs", "blk0x"),
            ("dev-libs", "blk0b", "1"),
            "<dev-libs/blk0x-2",
        ),
        (true, false),
        "DEPEND-rejected miss lands running, target parent stays target",
    );
    // Same edges, single-rooted: everything attributes target.
    let parent = entry(
        "blk0b",
        "1",
        false,
        vec![edge("blk0x", "<dev-libs/blk0x-2", 3)],
    );
    let entries = vec![parent];
    assert_eq!(
        skipped_update_roots(
            &entries,
            ("dev-libs", "blk0x"),
            ("dev-libs", "blk0b", "1"),
            "<dev-libs/blk0x-2",
        ),
        (false, false),
        "single-root runs keep the target attribution",
    );
    // A runtime edge keeps the miss with a running parent.
    let parent = entry("blk0b", "1", true, vec![edge("blk0x", "dev-libs/blk0x", 0)]);
    let entries = vec![parent];
    assert_eq!(
        skipped_update_roots(
            &entries,
            ("dev-libs", "blk0x"),
            ("dev-libs", "blk0b", "1"),
            "dev-libs/blk0x",
        ),
        (true, true),
        "RDEPEND keeps the miss in the parent's (running) root",
    );
    // Unknown parent: both target (today's rendering, documented).
    assert_eq!(
        skipped_update_roots(
            &entries,
            ("dev-libs", "blk0x"),
            ("dev-libs", "nope", "1"),
            "x",
        ),
        (false, false),
    );
}

/// Backlog #129 (review minor 3): the two `SkippedUpdate` sources
/// (backtrack-mask rows, direct-solve rows) collapse per slot
/// keeping the highest missed pkg, like real `_get_missed_updates`
/// (`lib/_emerge/depgraph.py:1553-1562`) -- a consecutive `dedup()`
/// could not do this. A slot present in both sources renders once,
/// at the higher version, whichever source holds it; equal
/// versions all stay (one row per parent) and exact duplicates
/// collapse to one, with mask rows leading.
#[test]
fn collapse_skipped_updates_keeps_the_highest_version_per_slot() {
    fn row(pkg: &str, ver: &str, atom: &str) -> SkippedUpdate {
        SkippedUpdate {
            category: "dev-libs".to_string(),
            package: pkg.to_string(),
            slot: "0".to_string(),
            skipped_version: ver.to_string(),
            skipped_sub_slot: "0".to_string(),
            skipped_repo: "testrepo".to_string(),
            skipped_use: Vec::new(),
            atom: atom.to_string(),
            consumer_cpv: "dev-libs/consumer-1:0/0::testrepo".to_string(),
            consumer_installed: false,
            consumer_use: Vec::new(),
            missed_targets_running_root: false,
            consumer_targets_running_root: false,
        }
    }
    // Mask source leads (first-seen order), direct source follows.
    let out = collapse_skipped_updates(vec![
        row("mgxc", "2", "=dev-libs/mgxc-1"),
        row("mgfc", "2", "=dev-libs/mgfc-2"),
        row("mgxc", "1.5", "=dev-libs/mgxc-1.5"),
        row("mgfc", "3.0", "=dev-libs/mgfc-1"),
        row("mgfc", "3.0", "=dev-libs/mgfc-1"),
        row("mgxd", "2", "=dev-libs/mgxd-2"),
        row("mgxd", "2", "<dev-libs/mgxd-3"),
    ]);
    assert_eq!(
        out.iter()
            .map(|s| (
                s.package.as_str(),
                s.skipped_version.as_str(),
                s.atom.as_str()
            ))
            .collect::<Vec<_>>(),
        vec![
            ("mgxc", "2", "=dev-libs/mgxc-1"),
            ("mgfc", "3.0", "=dev-libs/mgfc-1"),
            ("mgxd", "2", "=dev-libs/mgxd-2"),
            ("mgxd", "2", "<dev-libs/mgxd-3"),
        ]
    );
}

/// Backlog #291: the bt0 lone-record re-file matches a built
/// `:S/SS=` puller against the installed instance's own vdb sub-slot,
/// not the tree's metadata for that version.
#[test]
fn merge_same_slot_conflicts_refiles_a_built_puller_under_the_installed_sub_slot() {
    let base = slotundo_temp_dir("291-refile");
    let repo = base.join("repo");
    let dir = repo.join("dev-libs/foo");
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("foo-1.0.ebuild"),
        "EAPI=8\nDESCRIPTION=\"291\"\nSLOT=\"0/1\"\nKEYWORDS=\"amd64\"\n",
    )
    .unwrap();
    let repos = vec![RepoConfig {
        name: "testrepo".to_string(),
        location: repo.clone(),
        priority: 0,
        is_main: true,
        masters: vec![],
        profile_formats: vec![],
        cache_formats: vec![],
        aliases: vec![],
        sync_type: None,
        sync_uri: None,
        volatile: false,
        module_specific_options: vec![],
    }];
    let inst = |version: &str, sub: &str, installed: bool| SlotConflictInstance {
        version: version.to_string(),
        sub_slot: sub.to_string(),
        repo_name: "testrepo".to_string(),
        use_display: Vec::new(),
        parents: Vec::new(),
        installed,
    };
    // The installed foo-1.0 was built at 0/9; the tree's 1.0 says 0/1.
    let conflict = SlotConflict {
        category: "dev-libs".to_string(),
        package: "foo".to_string(),
        slot: "0".to_string(),
        resolved_version: "2.0".to_string(),
        conflicting_atom: "dev-libs/foo:0/9=".to_string(),
        instances: vec![inst("1.0", "9", true), inst("2.0", "2", false)],
    };
    let mut pullers: SlotPullers = HashMap::new();
    pullers.insert(
        ("dev-libs".to_string(), "foo".to_string()),
        vec![(
            "dev-libs".to_string(),
            "parent".to_string(),
            "1.0".to_string(),
            "dev-libs/foo:0/9=".to_string(),
        )],
    );
    let out = merge_same_slot_conflicts(&[conflict], &pullers, &repos, &test_config(), &base, true);
    let installed = out[0].instances.iter().find(|i| i.installed).unwrap();
    assert_eq!(
        installed.parents.len(),
        1,
        "the `:0/9=` puller files under the installed 0/9 instance"
    );
}

