/// Backlog #296: an installed holder's recorded `bdprov:0` is a seed
/// atom like a world atom -- it holds the slot-0 instance a slot-1
/// merge would otherwise uninstall; `:=` / bare edges hold nothing.
#[test]
fn set_seed_holds_the_instance_an_installed_holders_slot_edge_selects() {
    let merged = GraphEntry {
        outcome: PretendOutcome::Upgrade {
            from: "2".into(),
            to: "3".into(),
        },
        slot: Some("1".into()),
        sub_slot: Some("2".into()),
        ..graph_entry("app-misc", "bdprov", "3")
    };
    let held = |atoms: &[&str]| {
        let atoms: Vec<String> = atoms.iter().map(|a| (*a).to_string()).collect();
        set_seed_holds_instance(
            &atoms,
            std::slice::from_ref(&merged),
            "app-misc",
            "bdprov",
            "1",
            "0",
            "1",
        )
    };
    assert!(held(&["app-misc/bdprov:0"]));
    assert!(
        !held(&["app-misc/bdprov:="]),
        "a bare `:=` edge rebinds to the merge"
    );
    assert!(!held(&["app-misc/bdprov"]));
}

/// Backlog #289: a set atom that selects the old instance holds it
/// (real `SetArg` parent), a bare atom that the merged new instance
/// also matches does not.
#[test]
fn set_seed_holds_the_instance_only_a_slot_atom_selects() {
    let merged = GraphEntry {
        outcome: PretendOutcome::Upgrade {
            from: "2".into(),
            to: "3".into(),
        },
        slot: Some("1".into()),
        sub_slot: Some("2".into()),
        ..graph_entry("app-misc", "bdprov", "3")
    };
    let held = |atoms: &[&str]| {
        let atoms: Vec<String> = atoms.iter().map(|a| (*a).to_string()).collect();
        set_seed_holds_instance(
            &atoms,
            std::slice::from_ref(&merged),
            "app-misc",
            "bdprov",
            "1",
            "0",
            "1",
        )
    };
    assert!(held(&["app-misc/bdprov:0"]), "a slot atom selects slot 0");
    assert!(
        !held(&["app-misc/bdprov"]),
        "a bare atom selects the new slot"
    );
    assert!(!held(&["app-misc/bdprov:1"]), "another slot's atom");
    assert!(
        !held(&["@world", "!app-misc/bdprov:0"]),
        "sets and blockers"
    );
}

/// Backlog #288: an argument atom is a probe parent of its own cp and
/// vetoes a provider candidate it does not match (real
/// `_slot_operator_check_reverse_dependencies` over `_parent_atoms`).
#[test]
fn argument_probe_parents_veto_a_candidate_the_argument_does_not_match() {
    let mut parents: HashMap<(String, String), Vec<ProbeParent>> = HashMap::new();
    let atoms: HashSet<String> = ["=app-misc/mmprov-1", "!app-misc/blk", "app-misc/mmcons"]
        .iter()
        .map(|a| (*a).to_string())
        .collect();
    add_argument_probe_parents(&mut parents, &atoms);
    let provider = ("app-misc".to_string(), "mmprov".to_string());
    let consumer = ("app-misc".to_string(), "mmcons".to_string());
    assert!(
        !parents.contains_key(&("app-misc".to_string(), "blk".to_string())),
        "a blocker argument is not a parent"
    );
    let scheduled = BTreeSet::new();
    assert!(probe_refused(
        &parents,
        &scheduled,
        &provider,
        "app-misc/mmprov-3:1/2",
        &consumer
    ));
    assert!(!probe_refused(
        &parents,
        &scheduled,
        &provider,
        "app-misc/mmprov-1:0/1",
        &consumer
    ));
}

/// Backlog #129 (review round 2): rows naming the same missed pkg
/// render as one block with every parent line inside (real
/// `_show_missed_update_slot_conflicts`,
/// `lib/_emerge/depgraph.py:1650+`, over the single per-`(root,
/// slot_atom)` entry, `:1553-1562`) -- the `blk0b blk0c blk0a
/// --backtrack=0` oracle shape (bed `l0-fx-20260927T125711Z`: one
/// `dev-libs/blk0x:0` block for `-3` with both parents). Groups
/// keep first-seen order, parents keep row order; a different
/// missed version stays its own block.
#[test]
fn group_skipped_updates_merges_parents_of_the_same_missed_pkg() {
    fn row(ver: &str, atom: &str, consumer: &str) -> SkippedUpdate {
        SkippedUpdate {
            category: "dev-libs".to_string(),
            package: "blk0x".to_string(),
            slot: "0".to_string(),
            skipped_version: ver.to_string(),
            skipped_sub_slot: "0".to_string(),
            skipped_repo: "testrepo".to_string(),
            skipped_use: Vec::new(),
            atom: atom.to_string(),
            consumer_cpv: consumer.to_string(),
            consumer_installed: false,
            consumer_use: Vec::new(),
            missed_targets_running_root: false,
            consumer_targets_running_root: false,
        }
    }
    let rows = vec![
        row("3", "<dev-libs/blk0x-2", "dev-libs/blk0b-1:0/0::testrepo"),
        row("3", "<dev-libs/blk0x-3", "dev-libs/blk0c-1:0/0::testrepo"),
        row("2", "<dev-libs/blk0x-2", "dev-libs/blk0b-1:0/0::testrepo"),
    ];
    let groups = group_skipped_updates(&rows);
    assert_eq!(groups.len(), 2, "same missed pkg renders one block");
    assert_eq!(
        groups[0]
            .iter()
            .map(|s| s.atom.as_str())
            .collect::<Vec<_>>(),
        vec!["<dev-libs/blk0x-2", "<dev-libs/blk0x-3"],
        "both parents stay inside, in row order",
    );
    assert_eq!(groups[1].len(), 1);
    assert_eq!(groups[1][0].skipped_version, "2");
}

/// Backlog #230: the skipped-update block renders real's full
/// `pkg_use_display`, not the IUSE-only approximation -- the
/// effective USE masked to the valid-IUSE domain, one group per
/// non-hidden `USE_EXPAND` var, `( )`-wrapped force/mask flags.
/// Pure-function level: masking plus assembly, no repos needed.
#[test]
fn skipped_use_display_masks_to_the_valid_domain_and_groups_expands() {
    let config = portage_profile::Config {
        use_expand: HashSet::from(["ELIBC".to_string(), "CPU_FLAGS_X86".to_string()]),
        use_expand_hidden: HashSet::from(["CPU_FLAGS_X86".to_string()]),
        iuse_effective: HashSet::from(["elibc_glibc".to_string(), "elibc_musl".to_string()]),
        archlist: HashSet::from(["amd64".to_string(), "x86".to_string()]),
        ..Default::default()
    };
    // EAPI 8 (iuse_effective rule): only declared IUSE and
    // IUSE_EFFECTIVE survive; the profile-global `foo` and the
    // forced-but-undeclared `globalforceflag` are masked out, while
    // the implicit `elibc_glibc` is kept and grouped.
    let explicit: HashSet<String> = HashSet::from(["alpha".to_string(), "beta".to_string()]);
    let use_flags: HashSet<String> = HashSet::from([
        "alpha".to_string(),
        "foo".to_string(),
        "amd64".to_string(),
        "globalforceflag".to_string(),
        "elibc_glibc".to_string(),
    ]);
    let kept = mask_use_to_valid_domain(
        &explicit,
        &use_flags,
        true,
        &config,
        &HashSet::from(["globalforceflag".to_string()]),
    );
    assert_eq!(
        kept,
        HashSet::from(["alpha".to_string(), "elibc_glibc".to_string()]),
        "IUSE_EFFECTIVE keeps the implicit expand flag only",
    );
    assert_eq!(
        assemble_pkg_use_display(
            &kept,
            &explicit,
            &HashSet::from(["globalforceflag".to_string()]),
            &config,
        ),
        vec![
            ("USE".to_string(), "alpha -beta".to_string()),
            ("ELIBC".to_string(), "glibc".to_string()),
        ],
        "real `emerge --info dev-libs/pkginfopkg` shape: USE=\"alpha -beta\" ELIBC=\"glibc\"",
    );
    // Pre-EAPI-5 rule: ARCH is kept-then-discarded, hidden-expand
    // flags are kept but their group is hidden, and per-package
    // force/mask membership keeps a flag no IUSE declares (and wraps
    // it). `other_vars["ARCH"]` is the profile ARCH scalar.
    let mut pre_config = portage_profile::Config {
        use_expand: HashSet::from(["CPU_FLAGS_X86".to_string()]),
        use_expand_hidden: HashSet::from(["CPU_FLAGS_X86".to_string()]),
        archlist: HashSet::from(["amd64".to_string()]),
        ..Default::default()
    };
    pre_config
        .other_vars
        .insert("ARCH".to_string(), "amd64".to_string());
    let kept_pre = mask_use_to_valid_domain(
        &HashSet::new(),
        &use_flags,
        false,
        &pre_config,
        &HashSet::from(["globalforceflag".to_string()]),
    );
    assert_eq!(
        kept_pre,
        HashSet::from(["amd64".to_string(), "globalforceflag".to_string()]),
        "ARCH + useforce survive the pre-EAPI-5 mask; foo/alpha/elibc drop",
    );
    assert_eq!(
        assemble_pkg_use_display(
            &kept_pre,
            &HashSet::new(),
            &HashSet::from(["globalforceflag".to_string()]),
            &pre_config,
        ),
        vec![("USE".to_string(), "(globalforceflag)".to_string())],
        "ARCH discarded, hidden group skipped, forced flag wrapped",
    );
}

