#[test]
fn parse_updates_content_keeps_move_and_slotmove_drops_the_rest() {
    let cmds = parse_updates_content(
        "move dev-libs/foo dev-libs/bar\n\
         # a comment line, not a directive\n\
         slotmove dev-libs/baz 0 1\n\
         move dev-libs/foo dev-libs/foo-1.0\n\
         frobnicate dev-libs/x dev-libs/y\n\
         move only-two-tokens\n\
         slotmove dev-libs/qux 0\n",
    );
    assert_eq!(
        cmds,
        vec![
            UpdateCmd::Move {
                old: ("dev-libs".into(), "foo".into()),
                new: ("dev-libs".into(), "bar".into()),
            },
            UpdateCmd::SlotMove {
                cp: ("dev-libs".into(), "baz".into()),
                old_slot: "0".into(),
                new_slot: "1".into(),
            },
        ]
    );
}

#[test]
fn apply_move_and_slotmove_to_a_token_preserve_the_other_atom_parts() {
    let old = ("dev-libs".to_string(), "foo".to_string());
    let new = ("sys-libs".to_string(), "bar".to_string());
    assert_eq!(
        apply_move_to_token("dev-libs/foo", &old, &new),
        "sys-libs/bar"
    );
    assert_eq!(
        apply_move_to_token(">=dev-libs/foo-1.2:3=", &old, &new),
        ">=sys-libs/bar-1.2:3="
    );
    assert_eq!(
        apply_move_to_token("!dev-libs/foo", &old, &new),
        "!sys-libs/bar"
    );
    // A different cp is untouched.
    assert_eq!(
        apply_move_to_token("dev-libs/other", &old, &new),
        "dev-libs/other"
    );

    let cp = ("dev-libs".to_string(), "baz".to_string());
    assert_eq!(
        apply_slotmove_to_token("dev-libs/baz:0", &cp, "0", "1"),
        "dev-libs/baz:1"
    );
    assert_eq!(
        apply_slotmove_to_token("dev-libs/baz:0/0=", &cp, "0", "1"),
        "dev-libs/baz:1/1="
    );
    // A versioned atom or a non-matching slot is left alone (real
    // update_dbentry's own restriction).
    assert_eq!(
        apply_slotmove_to_token("=dev-libs/baz-1.0:0", &cp, "0", "1"),
        "=dev-libs/baz-1.0:0"
    );
    assert_eq!(
        apply_slotmove_to_token("dev-libs/baz:2", &cp, "0", "1"),
        "dev-libs/baz:2"
    );
}

/// #119: the dep-string rewrite is lazy -- `None` when no
/// `move`/`slotmove` touched a token (so the caller can skip its
/// insert and no output is allocated), `Some(rewritten)` otherwise,
/// with the surrounding whitespace, `||`/`(`/`)` and `use?` tokens
/// preserved byte-for-byte.
#[test]
fn apply_updates_to_dep_string_reports_unchanged_and_rewrites_only_moved_tokens() {
    let old = ("dev-libs".to_string(), "oldname".to_string());
    let new = ("dev-libs".to_string(), "newname".to_string());
    let cmds = vec![UpdateCmd::Move {
        old: old.clone(),
        new: new.clone(),
    }];
    let targets: HashMap<String, HashSet<String>> =
        HashMap::from([(old.0.clone(), HashSet::from([old.1.clone()]))]);
    // No token's cp is a move target: unchanged, no allocation.
    assert_eq!(
        apply_updates_to_dep_string_with("dev-libs/keep >=dev-libs/keep-1.2:0=\n", &cmds, &targets),
        None
    );
    // The moved token is rewritten; newlines, indentation, operators
    // and the `|| ( )` group all survive.
    assert_eq!(
        apply_updates_to_dep_string_with(
            "dev-libs/keep\n  >=dev-libs/oldname-1.2:0= || ( dev-libs/oldname:0 )",
            &cmds,
            &targets
        ),
        Some("dev-libs/keep\n  >=dev-libs/newname-1.2:0= || ( dev-libs/newname:0 )".to_string())
    );
    // A conditional marker is never parsed as an atom.
    assert_eq!(
        apply_updates_to_dep_string_with("foo? ( dev-libs/foo )", &cmds, &targets),
        None
    );
    // A slotmove rewrites only a slot-qualified token.
    let slot_cp = ("dev-libs".to_string(), "baz".to_string());
    let slot_cmds = vec![UpdateCmd::SlotMove {
        cp: slot_cp.clone(),
        old_slot: "0".to_string(),
        new_slot: "1".to_string(),
    }];
    let slot_targets: HashMap<String, HashSet<String>> =
        HashMap::from([(slot_cp.0.clone(), HashSet::from([slot_cp.1.clone()]))]);
    assert_eq!(
        apply_updates_to_dep_string_with(
            "dev-libs/baz:0 dev-libs/baz-tools:0",
            &slot_cmds,
            &slot_targets
        ),
        Some("dev-libs/baz:1 dev-libs/baz-tools:0".to_string())
    );
}

#[test]
fn atom_all_use_unmasked_is_true_for_the_unsatuseor_alternative() {
    // `dev-libs/unsatuseor`'s `||` group's first alternative is
    // `dev-libs/unsatusealt[unsatuseorflag]`: unsatusealt is visible
    // but the flag is off by default (IUSE declares it, nothing
    // enables it), and `unsatuseorflag` is in NO use.mask /
    // use.force profile file -- so real's bug-515584 probe
    // (`all_use_unmasked`) must keep the choice in the selectable
    // `unsat_use_*` bins, not demote it to `other`. The second
    // alternative (dev-libs/doesnotexist-unsatuseor) has no visible
    // ebuild at all.
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("fixture repos.conf resolves");
    assert!(atom_all_use_unmasked(
        &repos,
        "dev-libs/unsatusealt[unsatuseorflag]",
        &config,
        &[]
    ));
}

#[test]
fn atom_all_use_unmasked_is_false_when_the_violated_flag_is_in_use_mask() {
    // The `other`-demotion side of bug-515584: a `[use]` dep on a
    // flag that sits in the candidate's own use.mask is NOT "fixable
    // by a USE change", so the whole `||` choice drops out of every
    // selectable bin. `dev-libs/slotusetarget` has `=...-2.0` mask `x`
    // in the fixture profile (fixtures/repo/profiles/package.use.mask)
    // -- see the slotconflict fixture tests for the matching side.
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("fixture repos.conf resolves");
    // The 1.0 version keeps its +x default (unmasked) -- only the
    // masked 2.0 should probe false.
    let masked = atom_all_use_unmasked(&repos, "=dev-libs/slotusetarget-2.0[x]", &config, &[]);
    let unmasked = atom_all_use_unmasked(&repos, "=dev-libs/slotusetarget-1.0[x]", &config, &[]);
    assert!(!masked, "mask-affected x on 2.0 must demote to other");
    assert!(unmasked, "x default-enabled on 1.0 stays selectable");
}

#[test]
fn highest_available_candidate_ignoring_use_picks_the_use_unsatisfiable_ebuild() {
    // Real `mydbapi_match_pkgs(atom.without_use)[-1]`: asking for
    // `dev-libs/unsatusealt[unsatuseorflag]` must still find
    // unspecified-use candidate `unsatusealt-1.0` (the `[...]` block
    // stripped) -- the seed for both the mask/force probe and the
    // violated-flag list. The hard dep would find NO candidate
    // (`doesnotexist-unsatuseor`).
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("fixture repos.conf resolves");
    let (candidate_str, keywords, iuse, use_flags, slot) =
        highest_available_candidate_ignoring_use(
            &repos,
            "dev-libs/unsatusealt[unsatuseorflag]",
            "dev-libs",
            "unsatusealt",
            &config,
            &[],
        )
        .expect("an ignoring-use candidate exists");
    assert_eq!(
        candidate_str, "dev-libs/unsatusealt-1.0:0/0::testrepo",
        "the sole visible version is found"
    );
    assert!(keywords.contains(&"amd64".to_string()));
    assert!(iuse.contains("unsatuseorflag"));
    assert!(!use_flags.contains("unsatuseorflag"), "off by default");
    assert_eq!(slot, "0");

    assert!(
        highest_available_candidate_ignoring_use(
            &repos,
            "dev-libs/doesnotexist-unsatuseor",
            "dev-libs",
            "doesnotexist-unsatuseor",
            &config,
            &[],
        )
        .is_none()
    );
}

#[test]
fn highest_available_candidate_ignoring_use_honours_extra_constraints() {
    // F5: real's `mydbapi` in `dep_zapdeps` is `_dep_check_composite_db`,
    // which honours the `'backtrack` loop's accumulated
    // `runtime_pkg_mask` -- so once backtracking excludes the highest
    // version of a `cat/pkg`, the bug-515584 probe must be seeded from
    // the highest *unmasked* version instead. `dev-libs/slotusetarget`
    // has two visible versions (1.0, 2.0); a negative constraint
    // excluding 2.0 must fall back to 1.0.
    let root = fixtures_root();
    let config = portage_profile::resolve_config(
        &root,
        &root.join("repo"),
        &[("overlay".to_string(), root.join("overlay"))],
        &[],
        "testrepo",
        &HashMap::new(),
        &root,
    )
    .expect("fixture config resolves");
    let repos = find_repos(&root).expect("fixture repos.conf resolves");
    let (unconstrained, ..) = highest_available_candidate_ignoring_use(
        &repos,
        "dev-libs/slotusetarget[x]",
        "dev-libs",
        "slotusetarget",
        &config,
        &[],
    )
    .expect("an ignoring-use candidate exists");
    assert_eq!(unconstrained, "dev-libs/slotusetarget-2.0:0/0::testrepo");

    let constraints = vec!["!=dev-libs/slotusetarget-2.0".to_string()];
    let (constrained, ..) = highest_available_candidate_ignoring_use(
        &repos,
        "dev-libs/slotusetarget[x]",
        "dev-libs",
        "slotusetarget",
        &config,
        &constraints,
    )
    .expect("an ignoring-use candidate exists under the constraint");
    assert_eq!(
        constrained, "dev-libs/slotusetarget-1.0:0/0::testrepo",
        "the highest UNMASKED candidate is returned once backtracking excludes 2.0"
    );
}

